// Fungsi Auto-Retry (Exponential Backoff) untuk koneksi API yang lebih stabil
const fetchWithRetry = async (url, options, maxRetries = 3) => {
  const delays = [1000, 2000, 4000];
  let lastResponse = null;
  let lastError = null;

  for (let i = 0; i <= maxRetries; i++) {
    try {
      const response = await fetch(url, options);
      lastResponse = response;
      
      if (response.ok || (response.status >= 400 && response.status < 500 && response.status !== 429 && response.status !== 401)) {
        return response;
      }
    } catch (error) {
      lastError = error;
    }
    
    if (i < maxRetries) {
      await new Promise(resolve => setTimeout(resolve, delays[i] || 2000));
    }
  }
  
  if (lastResponse) return lastResponse;
  throw lastError || new Error("Gagal terhubung ke server AI setelah beberapa percobaan.");
};

// Sanitasi otomatis untuk memastikan tidak ada handle lama yang ikut muncul di teks/naskah/caption AI maupun draft lama
const sanitizeBrandText = (str) => {
  if (typeof str !== 'string') return '';
  const legacyHandleRegex = new RegExp('@?arjuna[._-]daycare', 'gi');
  return str.replace(legacyHandleRegex, 'PAUD Arjuna Malang');
};

// Helper konversi aman nilai apa pun dari JSON AI menjadi string bersih (mencegah React Error #31 Blank Screen)
const safeStr = (val, fallback = '') => {
  const fbStr = fallback === null || fallback === undefined ? '' : sanitizeBrandText(String(fallback));
  if (val === null || val === undefined) return fbStr;
  if (typeof val === 'string') return sanitizeBrandText(val);
  if (typeof val === 'number' || typeof val === 'boolean') return String(val);
  if (Array.isArray(val)) {
    const joined = val.map((item) => safeStr(item, '')).filter(Boolean).join(', ');
    return joined || fbStr;
  }
  if (typeof val === 'object') {
    try {
      const entries = Object.entries(val)
        .map(([k, v]) => {
          const sv = safeStr(v, '');
          return sv ? `${k}: ${sv}` : '';
        })
        .filter(Boolean);
      return entries.length > 0 ? entries.join(' | ') : fbStr;
    } catch (e) {
      return fbStr;
    }
  }
  return sanitizeBrandText(String(val));
};

const safeHashtags = (val, fallback = '#arjunaDaycare #paudArjunaMalang #daycareMalang #kbTkMalang #tumbuhKembangAnak') => {
  if (!val) return fallback;
  if (Array.isArray(val)) {
    const tags = val
      .map((item) => safeStr(item, '').trim())
      .filter(Boolean)
      .map((t) => (t.startsWith('#') ? t : `#${t.replace(/\s+/g, '')}`));
    return tags.length > 0 ? tags.join(' ') : fallback;
  }
  const s = safeStr(val, '').trim();
  return s || fallback;
};

// Helper akses localStorage aman untuk sandbox iframe Gemini Canvas / browser ketat
const safeStorageGet = (key) => {
  try {
    if (typeof window !== 'undefined' && window.localStorage) {
      return window.localStorage.getItem(key);
    }
  } catch (e) {}
  return null;
};

const safeStorageSet = (key, value) => {
  try {
    if (typeof window !== 'undefined' && window.localStorage) {
      window.localStorage.setItem(key, value);
    }
  } catch (e) {}
};

// Helper ekstraksi JSON bersih dari respons LLM mana pun (termasuk model gratis/OpenRouter/DeepSeek/Gemini 2.5)
const cleanAndParseJSON = (rawText) => {
  if (!rawText) throw new Error("Respons AI kosong.");
  if (typeof rawText === 'object') return rawText;
  let cleaned = String(rawText)
    .replace(/<think>[\s\S]*?<\/think>/gi, '') // Hapus tag <think> jika pakai model reasoning
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const tryParse = (str) => {
    try {
      return JSON.parse(str);
    } catch (e1) {
      // Perbaiki trailing comma sebelum } atau ] yang sering muncul dari LLM
      const fixed = str.replace(/,\s*([}\]])/g, '$1');
      return JSON.parse(fixed);
    }
  };

  try {
    return tryParse(cleaned);
  } catch (e) {
    const firstObj = cleaned.indexOf('{');
    const lastObj = cleaned.lastIndexOf('}');
    const firstArr = cleaned.indexOf('[');
    const lastArr = cleaned.lastIndexOf(']');

    const candidates = [];
    if (firstObj !== -1 && lastObj > firstObj) {
      candidates.push({ pos: firstObj, str: cleaned.substring(firstObj, lastObj + 1) });
    }
    if (firstArr !== -1 && lastArr > firstArr) {
      candidates.push({ pos: firstArr, str: cleaned.substring(firstArr, lastArr + 1) });
    }
    candidates.sort((a, b) => a.pos - b.pos);

    for (const cand of candidates) {
      try {
        return tryParse(cand.str);
      } catch (innerErr) {}
    }
    throw new Error("Format JSON dari AI belum lengkap. Silakan klik tombol Generate sekali lagi.");
  }
};

// Fungsi untuk mengkonversi PCM16 Base64 ke format Audio WAV
const base64ToWav = (base64, sampleRate = 24000) => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const buffer = new ArrayBuffer(44 + bytes.length);
  const view = new DataView(buffer);

  const writeString = (offset, string) => {
    for (let i = 0; i < string.length; i++) {
      view.setUint8(offset + i, string.charCodeAt(i));
    }
  };

  writeString(0, 'RIFF');
  view.setUint32(4, 36 + bytes.length, true);
  writeString(8, 'WAVE');
  writeString(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeString(36, 'data');
  view.setUint32(40, bytes.length, true);

  const audioData = new Uint8Array(buffer, 44);
  audioData.set(bytes);

  const blob = new Blob([buffer], { type: 'audio/wav' });
  return URL.createObjectURL(blob);
};

// --- Helper: Convert Base64 to Blob ---
const base64ToBlob = (base64, mimeType = 'image/png') => {
  const byteString = atob(base64.split(',')[1]);
  const ab = new ArrayBuffer(byteString.length);
  const ia = new Uint8Array(ab);
  for (let i = 0; i < byteString.length; i++) {
    ia[i] = byteString.charCodeAt(i);
  }
  return new Blob([ab], { type: mimeType });
};

// --- HELPER: Load JSZip & jsPDF Dinamis ---
const loadJSZip = async () => {
  if (window.JSZip) return window.JSZip;
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
    script.onload = () => resolve(window.JSZip);
    script.onerror = reject;
    document.body.appendChild(script);
  });
};

const loadJSPDF = async () => {
  if (window.jspdf) return window.jspdf;
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    script.onload = () => resolve(window.jspdf);
    script.onerror = reject;
    document.body.appendChild(script);
  });
};

// --- Helper: Buat Base Canvas Solid Sesuai Brand Identity Arjuna (Halaman 2 & 4 PDF) ---
const createArjunaBrandBaseImage = (slideType = 'content', aspectRatio = '1:1') => {
  const [rW, rH] = aspectRatio.split(':').map(Number);
  const width = 1080;
  const height = Math.round(1080 * (rH / rW));
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  if (slideType === 'cover') {
    // COVER SLIDE: Navy #1A3460 (Kepercayaan Dasar)
    const grad = ctx.createLinearGradient(0, 0, width, height);
    grad.addColorStop(0, '#1A3460');
    grad.addColorStop(1, '#13274A');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    // Soft decorative accent circle
    ctx.fillStyle = 'rgba(243, 94, 80, 0.08)';
    ctx.beginPath();
    ctx.arc(width * 0.85, height * 0.18, width * 0.28, 0, Math.PI * 2);
    ctx.fill();
  } else if (slideType === 'cta') {
    // CTA SLIDE: Coral #F35E50 (Aktivasi CTA)
    const grad = ctx.createLinearGradient(0, 0, width, height);
    grad.addColorStop(0, '#F35E50');
    grad.addColorStop(1, '#E04B3D');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = 'rgba(243, 188, 111, 0.14)';
    ctx.beginPath();
    ctx.arc(width * 0.85, height * 0.2, width * 0.25, 0, Math.PI * 2);
    ctx.fill();
  } else {
    // CONTENT SLIDE: Warm Cream #FFF8F3 dengan aksen Pink #F9C5CB & Gold #F3BC6F lembut
    ctx.fillStyle = '#FFF8F3';
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = 'rgba(249, 197, 203, 0.22)';
    ctx.beginPath();
    ctx.arc(width * 0.9, height * 0.12, width * 0.22, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'rgba(243, 188, 111, 0.15)';
    ctx.beginPath();
    ctx.arc(width * 0.1, height * 0.88, width * 0.18, 0, Math.PI * 2);
    ctx.fill();
  }

  return canvas.toDataURL('image/png');
};

// --- Helper: Cache & Render Logo Resmi PAUD Arjuna di Pojok Kiri Atas Semua Format ---
let _cachedArjunaLogoImg = null;
const loadArjunaLogoImage = () => {
  if (_cachedArjunaLogoImg && _cachedArjunaLogoImg.complete && _cachedArjunaLogoImg.naturalWidth > 0) {
    return Promise.resolve(_cachedArjunaLogoImg);
  }
  if (typeof window === 'undefined' || typeof Image === 'undefined') {
    return Promise.resolve(null);
  }
  return new Promise((resolve) => {
    const logoImg = new Image();
    logoImg.onload = () => {
      _cachedArjunaLogoImg = logoImg;
      resolve(logoImg);
    };
    logoImg.onerror = () => resolve(null);
    logoImg.src = ARJUNA_LOGO_DATA_URL;
  });
};

const drawArjunaLogoTopLeft = (ctx, logoImg, canvasWidth, canvasHeight, options = {}) => {
  const minDim = Math.min(canvasWidth, canvasHeight);
  const logoX = Math.round(minDim * 0.055);
  const logoY = Math.round(minDim * 0.048);
  if (!logoImg || !logoImg.width || !logoImg.height) {
    return { x: logoX, y: logoY, width: 0, height: 0, bottomY: Math.round(minDim * 0.16) };
  }
  const scaleFactor = options.scale || 0.155;
  const logoW = Math.round(minDim * scaleFactor);
  const logoH = Math.round(logoW * (logoImg.height / logoImg.width));
  const isDarkBg = Boolean(options.isDarkBg);

  ctx.save();
  ctx.imageSmoothingEnabled = true;
  if ('imageSmoothingQuality' in ctx) {
    ctx.imageSmoothingQuality = 'high';
  }
  if (isDarkBg) {
    ctx.shadowColor = 'rgba(255, 248, 243, 0.36)';
    ctx.shadowBlur = Math.max(8, Math.round(logoW * 0.08));
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 2;
  } else {
    ctx.shadowColor = 'rgba(26, 52, 96, 0.18)';
    ctx.shadowBlur = Math.max(6, Math.round(logoW * 0.06));
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = Math.max(2, Math.round(logoW * 0.02));
  }
  ctx.drawImage(logoImg, logoX, logoY, logoW, logoH);
  ctx.restore();

  return { x: logoX, y: logoY, width: logoW, height: logoH, bottomY: logoY + logoH };
};

// --- Helper: Stempel Logo Resmi di Pojok Kiri Atas untuk Frame Video / Reels / TikTok / Shorts / YouTube ---
const stampArjunaLogoOnFrame = async (base64Img, aspectRatioStr = '9:16') => {
  const logoImg = await loadArjunaLogoImage();
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const cleanRatio = aspectRatioStr.includes('9:16')
          ? '9:16'
          : aspectRatioStr.includes('16:9')
            ? '16:9'
            : aspectRatioStr.includes('4:5')
              ? '4:5'
              : '1:1';
        const [rW, rH] = cleanRatio.split(':').map(Number);
        const targetRatio = (rW || 1) / (rH || 1);
        const imgRatio = img.width / img.height;

        let sWidth = img.width;
        let sHeight = img.height;
        if (Math.abs(imgRatio - targetRatio) > 0.01) {
          if (imgRatio > targetRatio) {
            sWidth = img.height * targetRatio;
          } else {
            sHeight = img.width / targetRatio;
          }
        }
        const sx = Math.max(0, (img.width - sWidth) / 2);
        const sy = Math.max(0, (img.height - sHeight) / 2);

        const canvas = document.createElement('canvas');
        canvas.width = cleanRatio === '16:9' ? 1920 : 1080;
        canvas.height = Math.round(canvas.width / targetRatio);
        const ctx = canvas.getContext('2d');

        ctx.drawImage(img, sx, sy, sWidth, sHeight, 0, 0, canvas.width, canvas.height);
        drawArjunaLogoTopLeft(ctx, logoImg, canvas.width, canvas.height, { isDarkBg: true, scale: 0.15 });
        resolve(canvas.toDataURL('image/png'));
      } catch (e) {
        resolve(base64Img);
      }
    };
    img.onerror = () => resolve(base64Img);
    img.src = base64Img;
  });
};

