// --- Helper: Render Text, Rasio & Brand Identity Arjuna (Wajib Logo Kiri Atas, Tanpa Tulisan Handle) ---
const processCanvasImage = async (base64Img, options) => {
  const { 
    text, fontStyle = "'Nunito', sans-serif", 
    isHook = false, isLastSlide = false, aspectRatio = '1:1', 
    applyText = true, offsetX = 0, offsetY = 0, zoom = 1,
    textAlign = 'left', textPosition = 'center', highlightColor = '#F35E50',
    arjunaBrandMode = true, isSolidBrandCard = false
  } = options;
  
  await document.fonts.ready;
  const logoImg = await loadArjunaLogoImage();
  
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const [rW, rH] = aspectRatio.split(':').map(Number);
      const targetRatio = rW / rH;
      const imgRatio = img.width / img.height;

      let sWidth = img.width;
      let sHeight = img.height;
      
      if (Math.abs(imgRatio - targetRatio) > 0.01) {
        if (imgRatio > targetRatio) {
          sWidth = img.height * targetRatio;
        } else {
          sHeight = img.width / targetRatio;
        }
      }

      const zoomedWidth = sWidth / zoom;
      const zoomedHeight = sHeight / zoom;

      const maxOffsetX = img.width - zoomedWidth;
      const maxOffsetY = img.height - zoomedHeight;
      
      let sx = (img.width - zoomedWidth) / 2 + (maxOffsetX * (offsetX / 100));
      let sy = (img.height - zoomedHeight) / 2 + (maxOffsetY * (offsetY / 100));

      sx = Math.max(0, Math.min(sx, maxOffsetX));
      sy = Math.max(0, Math.min(sy, maxOffsetY));

      const canvas = document.createElement('canvas');
      canvas.width = Math.max(sWidth, 1080);
      canvas.height = Math.round(canvas.width / targetRatio);
      const ctx = canvas.getContext('2d');

      // 1. Gambar Background
      ctx.drawImage(img, sx, sy, zoomedWidth, zoomedHeight, 0, 0, canvas.width, canvas.height);

      const margin = canvas.width * 0.085;
      const isContentSlide = !isHook && !isLastSlide;
      const useLightContentCard = arjunaBrandMode && isContentSlide && isSolidBrandCard;

      if (applyText) {
        // 2. Overlay sesuai jenis slide Brand Reference Arjuna
        if (!isSolidBrandCard) {
          if (isHook) {
            ctx.fillStyle = arjunaBrandMode ? 'rgba(26, 52, 96, 0.82)' : 'rgba(0, 0, 0, 0.65)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
          } else if (isLastSlide) {
            ctx.fillStyle = arjunaBrandMode ? 'rgba(243, 94, 80, 0.85)' : 'rgba(0, 0, 0, 0.60)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
          } else {
            ctx.fillStyle = arjunaBrandMode ? 'rgba(26, 52, 96, 0.76)' : 'rgba(0, 0, 0, 0.55)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
          }
        }

        // 3. Watermark Latar "Arjuna" Transparan
        ctx.save();
        const wmSize = Math.floor(canvas.width * 0.24);
        ctx.font = `900 ${wmSize}px 'Nunito', system-ui, sans-serif`;
        ctx.fillStyle = useLightContentCard
          ? 'rgba(26, 52, 96, 0.045)'
          : 'rgba(255, 255, 255, 0.055)';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText('Arjuna', canvas.width - margin * 0.5, canvas.height * 0.48);
        ctx.restore();
      }

      // 4. WAJIB: Logo Resmi PAUD Arjuna di Pojok Kiri Atas Setiap Slide/Konten
      const logoRect = drawArjunaLogoTopLeft(ctx, logoImg, canvas.width, canvas.height, {
        isDarkBg: applyText ? !useLightContentCard : true,
        scale: 0.155
      });

      if (applyText) {
        // 5. Garis Footer Halus & Indikator Geser (TANPA TULISAN HANDLE @)
        ctx.save();
        const footerY = canvas.height - margin * 0.82;
        const dividerY = footerY - canvas.width * 0.042;
        ctx.strokeStyle = useLightContentCard
          ? 'rgba(26, 52, 96, 0.12)'
          : 'rgba(255, 255, 255, 0.18)';
        ctx.lineWidth = Math.max(2, Math.floor(canvas.width * 0.002));
        ctx.beginPath();
        ctx.moveTo(margin, dividerY);
        ctx.lineTo(canvas.width - margin, dividerY);
        ctx.stroke();

        if (!isLastSlide) {
          const swipeFontSize = Math.max(Math.floor(canvas.width * 0.022), 14);
          ctx.font = `800 ${swipeFontSize}px 'Nunito', system-ui, sans-serif`;
          ctx.fillStyle = useLightContentCard ? 'rgba(26, 52, 96, 0.60)' : 'rgba(255, 255, 255, 0.72)';
          ctx.textAlign = 'right';
          ctx.textBaseline = 'bottom';
          ctx.fillText("Geser 👉", canvas.width - margin, footerY);
        }
        ctx.restore();

        // 6. Tipografi Nunito & Smart Scale Teks Utama (Aman di Bawah Logo Kiri Atas)
        const safeText = sanitizeBrandText(typeof text === 'string' ? text : JSON.stringify(text || ""));
        const effectiveFont = fontStyle || "'Nunito', sans-serif";
        let fontSize = isHook
          ? Math.floor(canvas.width * 0.066)
          : isLastSlide
            ? Math.floor(canvas.width * 0.060)
            : Math.floor(canvas.width * 0.045);

        const safeTopY = logoRect.bottomY + Math.round(canvas.height * 0.042);
        const safeBottomY = isLastSlide
          ? Math.min(canvas.height * 0.72, dividerY - Math.round(canvas.height * 0.14))
          : (dividerY - Math.round(canvas.height * 0.038));
        const availableTextH = Math.max(canvas.height * 0.25, safeBottomY - safeTopY);

        let lines = [];
        const maxWidth = canvas.width - (margin * 2);
        const maxHeight = Math.min(isLastSlide ? canvas.height * 0.40 : canvas.height * 0.50, availableTextH);
        let lineHeight = fontSize * 1.32;

        const stripMd = (str) => str.replace(/\*/g, '');
        const fontWeight = isHook ? '900' : isLastSlide ? '900' : '800';

        while (fontSize > 18) {
          ctx.font = `${fontWeight} ${fontSize}px ${effectiveFont}`;
          lineHeight = fontSize * 1.32;
          lines = [];
          const paragraphs = safeText.split('\n');

          for (const para of paragraphs) {
            const words = para.trim().split(/\s+/);
            if (!words[0]) continue;
            let currentLine = words[0];
            for (let i = 1; i < words.length; i++) {
              const word = words[i];
              const width = ctx.measureText(stripMd(currentLine + " " + word)).width;
              if (width < maxWidth) {
                currentLine += " " + word;
              } else {
                lines.push(currentLine);
                currentLine = word;
              }
            }
            if (currentLine) lines.push(currentLine);
          }

          const isTooWide = lines.some(line => ctx.measureText(stripMd(line)).width > maxWidth);
          if (lines.length * lineHeight <= maxHeight && !isTooWide) break;
          fontSize -= 2;
        }

        // Shadow hanya untuk background gelap/foto
        if (!useLightContentCard) {
          ctx.shadowColor = 'rgba(0, 0, 0, 0.35)';
          ctx.shadowBlur = 10;
          ctx.shadowOffsetX = 0;
          ctx.shadowOffsetY = 2;
        } else {
          ctx.shadowColor = 'transparent';
          ctx.shadowBlur = 0;
        }
        ctx.textBaseline = 'middle';

        const totalTextHeight = lines.length * lineHeight;
        let startY;
        if (textPosition === 'top') {
          startY = safeTopY + (lineHeight / 2);
        } else if (textPosition === 'bottom') {
          startY = Math.max(safeTopY + (lineHeight / 2), safeBottomY - totalTextHeight + (lineHeight / 2));
        } else {
          const midAreaY = safeTopY + (availableTextH / 2);
          startY = Math.max(safeTopY + (lineHeight / 2), midAreaY - (totalTextHeight / 2) + (lineHeight / 2));
        }

        ctx.textAlign = 'left';
        const baseTextColor = useLightContentCard ? '#1A3460' : '#FFFFFF';
        const activeHighlightColor = isLastSlide
          ? '#F3BC6F'
          : (highlightColor || '#F35E50');

        lines.forEach((line, lineIdx) => {
          if (useLightContentCard && lines.length > 2 && lineIdx >= Math.ceil(lines.length / 2)) {
            ctx.font = `600 ${Math.max(Math.floor(fontSize * 0.78), 18)}px ${effectiveFont}`;
          } else {
            ctx.font = `${fontWeight} ${fontSize}px ${effectiveFont}`;
          }

          const cleanLine = stripMd(line);
          const lineWidth = ctx.measureText(cleanLine).width;

          let startX;
          if (textAlign === 'center') startX = (canvas.width - lineWidth) / 2;
          else if (textAlign === 'right') startX = canvas.width - margin - lineWidth;
          else startX = margin;

          const parts = line.split('*');
          let currentX = startX;

          parts.forEach((part, idx) => {
            if (part === '') return;
            ctx.fillStyle = idx % 2 === 1 ? activeHighlightColor : baseTextColor;
            ctx.fillText(part, currentX, startY);
            currentX += ctx.measureText(part).width;
          });

          startY += lineHeight;
        });

        // 7. Tombol CTA "Hubungi Kami →" pada Slide Terakhir
        if (isLastSlide && arjunaBrandMode) {
          ctx.save();
          ctx.shadowColor = 'rgba(0, 0, 0, 0.15)';
          ctx.shadowBlur = 12;
          ctx.shadowOffsetY = 4;

          const btnText = "Hubungi Kami →";
          const btnFontSize = Math.max(Math.floor(canvas.width * 0.028), 18);
          ctx.font = `800 ${btnFontSize}px 'Nunito', system-ui, sans-serif`;
          const textW = ctx.measureText(btnText).width;
          const btnPadX = canvas.width * 0.05;
          const btnPadY = canvas.width * 0.022;
          const btnW = textW + btnPadX * 2;
          const btnH = btnFontSize + btnPadY * 2;
          const btnX = textAlign === 'center' ? (canvas.width - btnW) / 2 : margin;
          const btnY = Math.min(startY + canvas.height * 0.035, dividerY - btnH - canvas.height * 0.02);

          ctx.fillStyle = '#FFFFFF';
          ctx.beginPath();
          if (typeof ctx.roundRect === 'function') {
            ctx.roundRect(btnX, btnY, btnW, btnH, btnH / 2);
          } else {
            const r = btnH / 2;
            ctx.moveTo(btnX + r, btnY);
            ctx.lineTo(btnX + btnW - r, btnY);
            ctx.quadraticCurveTo(btnX + btnW, btnY, btnX + btnW, btnY + r);
            ctx.lineTo(btnX + btnW, btnY + btnH - r);
            ctx.quadraticCurveTo(btnX + btnW, btnY + btnH, btnX + btnW - r, btnY + btnH);
            ctx.lineTo(btnX + r, btnY + btnH);
            ctx.quadraticCurveTo(btnX, btnY + btnH, btnX, btnY + btnH - r);
            ctx.lineTo(btnX, btnY + r);
            ctx.quadraticCurveTo(btnX, btnY, btnX + r, btnY);
            ctx.closePath();
          }
          ctx.fill();

          ctx.shadowColor = 'transparent';
          ctx.fillStyle = '#F35E50';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(btnText, btnX + btnW / 2, btnY + btnH / 2 + 1);
          ctx.restore();
        }
      }

      resolve(canvas.toDataURL('image/png'));
    };
    img.onerror = () => reject(new Error('Gagal memproses Canvas.'));
    img.src = base64Img;
  });
};

