// Helper formatter teks ramah tema terang PAUD Arjuna (anti-crash untuk tipe data apa pun)
const formatBoldText = (text) => {
  const str = safeStr(text, '');
  if (!str) return '';
  return str.split(/(\*\*.*?\*\*)/g).map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i} className="font-black text-[#F35E50]">{part.slice(2, -2)}</strong>;
    }
    return part;
  });
};

