// Error Boundary Pelindung Canvas (Menjamin layar TIDAK PERNAH blank putih jika terjadi anomali browser/AI)
class CanvasErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, errorMessage: '' };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, errorMessage: error?.message || String(error) };
  }
  componentDidCatch(error, info) {
    console.error('CanvasErrorBoundary menangkap error:', error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#FFF8F3] text-[#1A3460] flex items-center justify-center p-6" style={{ fontFamily: "'Nunito', system-ui, sans-serif" }}>
          <div className="max-w-lg w-full bg-white rounded-3xl border-2 border-[#1A3460] p-6 md:p-8 shadow-lg space-y-4 text-center">
            <div className="w-14 h-14 mx-auto rounded-2xl bg-[#F35E50]/15 text-[#F35E50] flex items-center justify-center">
              <AlertCircle className="w-8 h-8" />
            </div>
            <h2 className="text-xl font-black text-[#1A3460]">Tampilan Berhasil Dipulihkan</h2>
            <p className="text-xs font-semibold text-slate-600 leading-relaxed">
              Terjadi kendala ringan saat memproses tampilan data AI: <span className="font-mono text-[#F35E50]">{this.state.errorMessage}</span>
            </p>
            <button
              type="button"
              onClick={() => this.setState({ hasError: false, errorMessage: '' })}
              className="px-5 py-3 rounded-2xl bg-[#F35E50] hover:bg-[#e04b3d] text-white text-xs font-black border-2 border-[#1A3460] shadow-[0_3px_0_#1A3460] cursor-pointer"
            >
              ↺ Kembali ke Konten Guide Arjuna
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

