  // Fungsi Utama Panggilan Image AI (Mendukung Free Flux Pollinations, Kartu Brand Arjuna, dan Google Imagen)
  const generateImageUnified = async ({ prompt, aspectRatio = '1:1', slideType = 'content', referenceImages = [] }) => {
    const [rW, rH] = aspectRatio.split(':').map(Number);
    const width = 1080;
    const height = Math.round(1080 * ((rH || 1) / (rW || 1)));

    // 1. Jika memilih mode Kartu Brand Arjuna Murni
    if (aiConfig.imageEngine === 'arjuna_card') {
      return createArjunaBrandBaseImage(slideType, aspectRatio);
    }

    // 2. Jika memilih Google Imagen dan ada key / di dalam Canvas
    if (aiConfig.imageEngine === 'google_imagen') {
      const activeKey = (aiConfig.geminiKey || apiKey || '').trim();
      try {
        if (referenceImages && referenceImages.length > 0) {
          const imageParts = [{ text: prompt }];
          referenceImages.forEach(ref => {
            if (ref.label) imageParts.push({ text: ref.label });
            if (ref.base64 && ref.mimeType) {
              imageParts.push({ inlineData: { mimeType: ref.mimeType, data: ref.base64 } });
            }
          });
          const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-image-preview:generateContent?key=${activeKey}`;
          const res = await fetchWithRetry(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ contents: [{ role: 'user', parts: imageParts }], generationConfig: { responseModalities: ['IMAGE'] } })
          });
          const data = await res.json();
          const inlinePart = data.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
          if (inlinePart?.inlineData?.data) {
            return `data:image/png;base64,${inlinePart.inlineData.data}`;
          }
        } else {
          const url = `https://generativelanguage.googleapis.com/v1beta/models/imagen-4.0-generate-001:predict?key=${activeKey}`;
          const res = await fetchWithRetry(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ instances: { prompt }, parameters: { sampleCount: 1, aspectRatio } })
          });
          const data = await res.json();
          if (data.predictions?.[0]?.bytesBase64Encoded) {
            return `data:image/png;base64,${data.predictions[0].bytesBase64Encoded}`;
          }
        }
        throw new Error('Imagen tidak mengembalikan gambar.');
      } catch (err) {
        console.warn('Google Imagen gagal, fallback ke Flux AI Gratis:', err.message);
      }
    }

    // 3. Default / Fallback: Flux AI Gratis via Pollinations (Tanpa API Key, Konversi ke Base64 agar aman di Canvas)
    try {
      const seed = Math.floor(Math.random() * 999999);
      const cleanPrompt = `${prompt}, warm friendly Indonesian early childhood education atmosphere, safe and trustworthy, high quality photography, no text`;
      const pollUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(cleanPrompt)}?width=${width}&height=${height}&seed=${seed}&nologo=true&model=flux`;
      const resp = await fetch(pollUrl);
      if (!resp.ok) throw new Error('Gagal mengunduh gambar dari Flux Free Server.');
      const blob = await resp.blob();
      return await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
      });
    } catch (pollErr) {
      console.warn('Pollinations Flux gagal, menggunakan Kartu Visual Brand Arjuna:', pollErr.message);
      return createArjunaBrandBaseImage(slideType, aspectRatio);
    }
  };

