  const c_handleEditImage = async (slideIndex) => {
    const slideImgData = c_slideImages[slideIndex];
    if (!slideImgData || !c_editPrompt.trim()) return;

    setC_slideImages(prev => ({ ...prev, [slideIndex]: { ...prev[slideIndex], isLoading: true } }));

    try {
      const isHook = slideIndex === 0;
      const isLast = slideIndex === c_resultData.slides.length - 1;
      const slideType = isHook ? 'cover' : isLast ? 'cta' : 'content';
      const combinedPrompt = `${c_resultData.slides[slideIndex].imagePrompt || ''}. Edit instruction: ${c_editPrompt}`;

      const rawImageUrl = await generateImageUnified({
        prompt: combinedPrompt,
        aspectRatio: c_aspectRatio,
        slideType
      });

      const finalImageUrl = await processCanvasImage(rawImageUrl, {
        text: c_resultData.slides[slideIndex].text,
        fontStyle: c_fontFamily,
        isHook,
        isLastSlide: isLast,
        aspectRatio: c_aspectRatio,
        applyText: c_overlayText,
        textAlign: c_textAlign,
        textPosition: c_textPosition,
        highlightColor: c_highlightColor,
        arjunaBrandMode: c_arjunaBrandMode,
        isSolidBrandCard: false,
        slideNumber: slideIndex + 1,
        offsetX: 0,
        offsetY: 0,
        zoom: 1
      });

      setC_slideImages(prev => ({
        ...prev,
        [slideIndex]: { isLoading: false, url: finalImageUrl, rawUrl: rawImageUrl, isSolidBrandCard: false, offsetX: 0, offsetY: 0, zoom: 1, error: null }
      }));

      c_showToast('Gambar berhasil diperbarui!');
      setC_activeEditIndex(null);
      setC_editPrompt('');
    } catch (err) {
      setC_slideImages(prev => ({
        ...prev,
        [slideIndex]: { ...prev[slideIndex], isLoading: false, error: "Gagal edit: " + err.message }
      }));
    }
  };

