                                        {copiedIdeaPromptIndex === idx ? <CheckCircle2 className="w-3 h-3 text-emerald-600" /> : <Copy className="w-3 h-3" />}
                                        {copiedIdeaPromptIndex === idx ? 'Tersalin' : 'Salin Prompt'}
